typedef unsigned long uint64;

extern "C" unsigned int strlen(const char *);
extern "C" int toupper(int);
extern void error(const char *, ...);
extern void debug_print(const char *, ...);

#define assert(x) ((void)0)

class pstring
{
    static const char pc_to_ascii[64];
    static const char ascii_to_pc[128];
    uint64 pchunk[4];

public:
    unsigned length() const
    {
        register unsigned check;
        register unsigned ret_val = 0;

        for (unsigned i = 0; i < 4; ++i)
        {
            check = unsigned(pchunk[i] & 0xf);
            if (check == 0)
                return ret_val;
            else
                ret_val += check;
        }
        return ret_val;
    }

    const char *c_str() const;
    bool concatinate(const char *the_string);
};

bool pstring::concatinate(const char *the_string)
{
  unsigned len;
  unsigned i, j;
  int shift;
  unsigned end_found = 0;
  assert(the_string != 0);

  if (strlen(the_string) + length() > 40)
    return false;

  for (j=0; j<4; ++j)
  {
    len = unsigned (pchunk[j] & 0xf);
    if (len != 10)
      break;
  }

  i = 0;
  pchunk[j] &= ~0xf;
  shift = 58 - (len * 6);

  for (; j<4; ++j, shift = 58, len=0)
  {
    while (shift >= 4)
    {
      if (the_string[i] != '\0')
      {
        int temp = ascii_to_pc[the_string[i]];

        if ( temp == -1 )
          error( "Character cannot be packed: %c (%s)", the_string[i], the_string );

        assert (toupper(the_string[i]) == pc_to_ascii[temp]);

        pchunk[j] |= uint64(temp) << shift;
      }
      else
      {
        end_found = 1;
        break;
      }

      shift -= 6;
      ++i;
      ++len;
    }

    assert(len <= 10);
    pchunk[j] |= len;
    if (end_found == 1)
      break;
  }

  if (end_found == 0)
  {
    if (the_string[i] != '\0')
    {
      debug_print("String '%s' is too long to concatonate onto '%s'\n", the_string, this->c_str());
      return false;
    }
  }

  return true;
}
